    37	        assert(ret >= 0);
    38	
    39	        ret = gnutls_x509_dn_import(dn, &raw);
    40	        if (ret < 0)
    41	                goto cleanup;
    42	
    43	        /* If properly loaded, try to re-export in string */
    44	        ret = gnutls_x509_dn_get_str(dn, &out);
    45	        if (ret < 0) {
    46	                goto cleanup;
    47	        }
    48	
    49	        gnutls_free(out.data);
    50	
    51	cleanup:
    52	        gnutls_x509_dn_deinit(dn);
    53	        return 0;
    54	}
